from pathlib import Path
import json, shutil, html, os
import markdown
ROOT=Path(__file__).parent
OUT=ROOT/'dist'
BASE=os.environ.get('BASE_PATH','/manualdomaker-site').rstrip('/')
if OUT.exists(): shutil.rmtree(OUT)
OUT.mkdir();shutil.copytree(ROOT/'assets',OUT/'assets')
def page(title,body):
 return f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex, nofollow"><meta name="description" content="Manual do Maker: eletrônica, Linux e programação. Um novo espaço para aprender construindo."><meta name="theme-color" content="#142c29"><title>{title} · Manual do Maker</title><link rel="icon" href="{BASE}/assets/icon.svg"><link rel="stylesheet" href="{BASE}/assets/style.css"><script src="{BASE}/assets/app.js" defer></script></head><body><a class="skip" href="#conteudo">Pular para conteúdo</a><div class="preview">EM CONSTRUÇÃO <span>Uma prévia da próxima fase do Manual do Maker.</span><a href="https://www.manualdomaker.com/">Visitar o blog atual ↗</a></div><header><a class="brand" href="{BASE}/"><span class="brand-icon">m<span>_</span></span><span>MANUAL<br>DO MAKER<span class="dot">.</span></span></a><nav aria-label="Principal"><a href="{BASE}/#explorar">Explorar</a><a href="{BASE}/toolbox/">Ferramentas</a><a href="{BASE}/musica/">Música</a><a href="{BASE}/#projetos">Projetos</a><a href="{BASE}/#sobre">Sobre</a><a class="github" href="https://github.com/DjamesSuhanko">GitHub ↗</a></nav></header><main id="conteudo">{body}</main><footer><a class="footer-brand" href="{BASE}/">Manual do Maker<span>_</span></a><p>Por Djames Suhanko. Feito para quem gosta de descobrir como as coisas funcionam.</p><a href="https://www.manualdomaker.com/">Acervo original ↗</a><span>Modelo para aprovação · 2026</span></footer></body></html>'''
articles=json.loads((ROOT/'content/articles.json').read_text())
for source in sorted((ROOT/'content').glob('*.md')):
 parser=markdown.Markdown(extensions=['meta'])
 parser.convert(source.read_text())
 meta=parser.Meta
 articles.append({'title':meta['title'][0], 'category':meta.get('category',['Bastidores'])[0], 'description':meta.get('description',['Artigo do Manual do Maker.'])[0], 'href':f'{BASE}/artigos/{source.stem}/', 'local':True})
categories=['Todos']+list(dict.fromkeys(a['category'] for a in articles))
cards=''
for i,a in enumerate(articles):
 href=a.get('href', 'https://www.manualdomaker.com/article/'+a.get('slug','')+'/')
 label='MODELO' if a.get('local') else 'DO ACERVO'
 action='Ler artigo' if a.get('local') else 'Ler no blog original'
 cards+=f'''<article class="card" data-category="{a['category']}" data-search="{html.escape(a['title']+' '+a['description'])}"><a href="{href}" class="card-art art-{i}"><span class="art-label">{a['category'].upper()}</span><span class="diagram">{['◎','▥','⌁','▧','⤳','▣'][i % 6]}</span><span class="art-code">MDM / 0{i+1}</span></a><div class="card-body"><div class="eyebrow">{a['category']} <span>{label}</span></div><h3><a href="{href}">{a['title']}</a></h3><p>{a['description']}</p><a class="read" href="{href}">{action} <span>↗</span></a></div></article>'''
body=f'''<section class="hero"><div class="hero-copy"><p class="eyebrow"><span class="live-dot"></span> CURIOSIDADE EM ESTADO PRÁTICO</p><h1>Ideias na cabeça.<br><em>Mãos no circuito.</em></h1><p class="lead">Eletrônica, Linux e programação para sair do “e se?” e chegar ao “funcionou”. Um projeto de cada vez.</p><div class="hero-actions"><a class="button" href="#explorar">Encontrar meu próximo projeto <span>↗</span></a><a class="text-link" href="#sobre">Conheça o Manual ↓</a></div><p class="hero-foot">DESDE 2013 <span>·</span> CONHECIMENTO QUE SE COMPARTILHA</p></div><div class="hero-art" aria-label="Ilustração de uma placa eletrônica"><div class="board-top">LABORATÓRIO ABERTO <span>● ONLINE</span></div><svg viewBox="0 0 480 340" role="img" aria-label="Circuito com processador Maker"><g fill="none" stroke="#43655b" stroke-width="2"><path d="M0 80h120l65 65M0 260h115l65-70M480 70H360l-65 65M480 280H355l-65-65M215 0v95M245 0v95M275 0v95M215 245v95M245 245v95M275 245v95"/><path d="M0 110h100l50 50M480 110h-100l-50 50M0 295h135l45-45M480 310H345l-45-45"/><rect x="160" y="90" width="165" height="165" rx="12"/></g><g fill="#e6b971"><circle cx="120" cy="80" r="5"/><circle cx="360" cy="70" r="5"/><circle cx="115" cy="260" r="5"/><circle cx="355" cy="280" r="5"/></g><rect x="175" y="105" width="135" height="135" rx="8" fill="#10251f" stroke="#d1ae72"/><text x="242" y="168" text-anchor="middle" fill="#eac187" font-size="34" font-family="monospace">&lt;/&gt;</text><text x="242" y="204" text-anchor="middle" fill="#a5b4a1" font-size="12" letter-spacing="4" font-family="monospace">MAKER</text></svg><div class="board-bottom"><span>ENTRADA: CURIOSIDADE<br>SAÍDA: POSSIBILIDADES</span><span>REV. 01<br>23° S / BR</span></div></div></section><div class="topic-strip"><span>APRENDER. EXPERIMENTAR. COMPARTILHAR.</span><span>ESP32 / ARDUINO / LINUX / CÓDIGO ABERTO</span></div><section id="explorar" class="explore"><div class="section-heading"><div><p class="eyebrow">DA BANCADA PARA VOCÊ</p><h2>Explore o acervo<span>.</span></h2></div><p>Uma seleção do blog atual.<br>Links do acervo e um artigo demonstrativo.</p></div><div class="filter-bar"><div class="filters" role="group" aria-label="Filtrar por assunto">{''.join(f'<button type="button" data-filter="{x}" aria-pressed="{str(x=="Todos").lower()}">{x}</button>' for x in categories)}</div><label class="search"><span>⌕</span><input id="search" type="search" placeholder="O que você quer criar?" aria-label="Buscar artigos"></label></div><p id="result-count" class="result-count" aria-live="polite">{len(articles)} artigos selecionados</p><div class="cards">{cards}</div><p id="empty" hidden>Nenhum artigo encontrado. Experimente outro termo ou assunto.</p></section><section id="projetos" class="project"><div><p class="eyebrow">DO TEXTO AO TERMINAL</p><h2>O projeto continua<br>no código<span>_</span></h2><p>O tutorial explica. O repositório deixa você experimentar, adaptar e ir além. Esse é o caminho da nova casa do Manual.</p><a class="button" href="{BASE}/artigos/ola-maker/">Conhecer o modelo de artigo ↗</a></div><div class="terminal"><div class="terminal-top"><i></i><i></i><i></i><span>caderno-do-maker.md</span></div><pre><span># Uma ideia vira projeto</span>\n\n01  Entenda o que vamos construir\n02  Separe os componentes\n03  Explore o código-fonte\n04  Teste. Ajuste. Compartilhe.\n\n<b>→ Seu próximo aprendizado começa aqui.</b></pre><a href="https://github.com/DjamesSuhanko">Explorar repositórios de Djames ↗</a></div></section><section id="sobre" class="about"><p class="eyebrow">PRAZER, MANUAL DO MAKER.</p><h2>Aprender fazendo.<br>E compartilhar o caminho.</h2><div><p>Sou Djames Suhanko. O Manual do Maker reúne minha curiosidade por embarcados, Linux e programação, com projetos e experiências para quem também gosta de colocar a mão na massa.</p><p>Esta é uma proposta para a nova casa do blog. O acervo continua disponível no site original enquanto preparamos, com cuidado, a próxima etapa.</p><a class="text-link" href="https://www.manualdomaker.com/">Visitar o acervo completo ↗</a></div></section>'''
(OUT/'index.html').write_text(page('Aprenda construindo',body))
for source in (ROOT/'content').glob('*.md'):
 md=markdown.Markdown(extensions=['fenced_code','tables','toc','meta'])
 content=md.convert(source.read_text()); title=md.Meta['title'][0]
 target=OUT/'artigos'/source.stem;target.mkdir(parents=True)
 article=f'<div class="article-layout"><a class="text-link" href="{BASE}/#explorar">← Voltar ao início</a><p class="eyebrow">MODELO EDITORIAL · CONTEÚDO DEMONSTRATIVO</p><h1>{title}</h1><p class="article-intro">Uma amostra de como os próximos tutoriais poderão ser apresentados.</p><div class="article-grid"><article class="prose">{content}</article><aside><h2>Neste artigo</h2>{md.toc}<a href="https://github.com/DjamesSuhanko/manualdomaker-site">Repositório deste site ↗</a></aside></div></div>'
 (target/'index.html').write_text(page(title,article))
(OUT/'404.html').write_text(page('Página não encontrada',f'<section class="article-layout"><p class="eyebrow">ERRO 404</p><h1>Esse circuito está aberto.</h1><p>O endereço não existe nesta prévia.</p><a class="button" href="{BASE}/">Voltar ao início</a></section>'))
(OUT/'.nojekyll').touch()
print('Site gerado em',OUT)

from tools_pages import build_tools
build_tools(OUT, BASE, page)

from music_pages import build_music
build_music(OUT, BASE, page)
